#include "trisolv.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide. */
static
void init_array(int n,
                Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                Halide::Buffer<num_t, 1> x,
                Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(Expr(-999));

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) so that j (the column index) is the
    // fast‑varying dimension for better locality in the inner products.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // ------------------------------------------------------------------
    // Scheduling for initialization
    //
    // The initialization cost is O(n^2) for L and O(n) for x, b.
    // We tile and vectorize L along the fast‑varying j dimension
    // and parallelize across rows; for x and b we split, vectorize,
    // and parallelize across i. This keeps memory accesses contiguous
    // and exploits available cores.
    // ------------------------------------------------------------------
    Target tgt = get_jit_target_from_environment();
    const int vec_width = tgt.natural_vector_size(type_of<num_t>());
    const int tile_i = 64;   // tunable row tile
    const int tile_j = 64;   // tunable col tile

    // 1D initializations: split i into outer/inner, parallelize outer,
    // vectorize inner.
    Var io("io"), ii("ii");
    init_x
        .split(i, io, ii, tile_i)
        .vectorize(ii, vec_width)
        .parallel(io);
    init_b
        .split(i, io, ii, tile_i)
        .vectorize(ii, vec_width)
        .parallel(io);

    // 2D initialization for L: tile in (j, i), parallelize outer i-tiles,
    // and vectorize across the fast‑varying j dimension inside each tile.
    Var jo("jo"), ji("ji"), ioL("ioL"), iiL("iiL");
    init_L
        .tile(j, i, jo, ioL, ji, iiL, tile_j, tile_i)
        .vectorize(ji, vec_width)
        .parallel(ioL);

    // Realize into the given buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We express the j-loop as a reduction over RDom, and drive the
    // i-loop from the host, updating x one element at a time.
    //
    // L is stored as L_param(j, i_param).
    // -----------------------------------------------------------------

    Func xi("xi");          // accumulates b[i] - sum_{j<i} L[i][j]*x[j]
    Func xi_div("xi_div");  // final x[i] = xi / L[i][i]

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Start from b[i]
    xi() = b_param(i_param);

    // To make the reduction clearly associative and enable vectorization,
    // we express the subtraction as an addition of a negated term:
    //   xi = b[i] + sum_j ( -L[i][j] * x[j] )
    Expr minus_one = cast<num_t>(Expr(-1));
    xi() += minus_one * L_param(r, i_param) * x_param(r);

    // Divide by the diagonal entry L[i][i] (L_param(i, i))
    xi_div() = xi() / L_param(i_param, i_param);

    // -----------------------------------------------------------------
    // Bind ImageParams to our Buffers and provide layout/extent hints
    // so Halide can assume and optimize for dense row-major layouts.
    // -----------------------------------------------------------------
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // Explicit bounds/strides improve bounds inference and codegen.
    Expr n_expr = Expr(n);
    L_param.dim(0).set_bounds(0, n_expr).set_stride(1);       // j: contiguous
    L_param.dim(1).set_bounds(0, n_expr);                     // i
    x_param.dim(0).set_bounds(0, n_expr).set_stride(1);
    b_param.dim(0).set_bounds(0, n_expr).set_stride(1);

    // -----------------------------------------------------------------
    // Scheduling for the triangular solve kernel
    //
    // The outer loop over i is inherently sequential due to the data
    // dependence on x[0..i-1]. We therefore keep the i-loop on the host,
    // but aggressively optimize the inner reduction over j:
    //
    //  - vectorize the reduction RVar r across the fast-varying j
    //    dimension (L(j, i) and x(j) are both contiguous in memory).
    //  - keep xi and xi_div at compute_root (they are 0-D Funcs).
    // -----------------------------------------------------------------
    Target tgt = get_jit_target_from_environment();
    const int vec_width = tgt.natural_vector_size(type_of<num_t>());

    xi.compute_root();
    {
        RVar r_outer("r_outer"), r_inner("r_inner");
        // Split the reduction domain and vectorize the inner part.
        xi.update()
            .split(r, r_outer, r_inner, vec_width)
            .vectorize(r_inner);
    }
    xi_div.compute_root();

    // JIT-compile the pipeline once, for the chosen target.
    xi_div.compile_jit(tgt);

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar xi_div() for this i
        Halide::Buffer<num_t> xi_buf = xi_div.realize();

        // Update x[i] on the host (x_param points into the same storage,
        // so subsequent iterations see the updated prefix x[0..i]).
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
