constexpr int INIT_TILE_I      = 32;  // tile height  for L init
constexpr int INIT_TILE_J      = 32;  // tile width   for L init
constexpr int REDUCTION_UNROLL = 4;   // unroll factor for inner j‑reduction

/* Array initialization translated to Halide, with an optimized schedule. */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Var io("io"), jo("jo"), ii("ii"), ji("ji"), tile("tile");

    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    const Expr neg_999 = cast<num_t>(Expr(-999));
    init_x(i) = neg_999;

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i) so that j is the fast‑varying dimension.
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // --------------------------
    // Scheduling for init stage
    // --------------------------

    // 1D inits (x and b): parallelize over i and vectorize within each scanline.
    init_x
        .compute_root()
        .parallel(i)
        .vectorize(i, INIT_VEC_WIDTH);

    init_b
        .compute_root()
        .parallel(i)
        .vectorize(i, INIT_VEC_WIDTH);

    // 2D init for L:
    // Tile the (j,i) space to improve locality and enable multi‑core parallelism.
    // We parallelize over tiles and vectorize inside each tile along j (the
    // contiguous dimension).
    init_L
        .compute_root()
        .tile(j, i, jo, io, ji, ii, INIT_TILE_J, INIT_TILE_I)
        .fuse(jo, io, tile)
        .parallel(tile)
        .vectorize(ji, INIT_VEC_WIDTH);

    // --------------------------
    // Realize into the Buffers
    // --------------------------
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We express the j-loop as a reduction over RDom, and drive the
    // i-loop from the host, updating x one element at a time. This
    // preserves the original loop-carried dependency in i.
    // -----------------------------------------------------------------

    Func xi("xi");         // accumulates b[i] - sum_{j<i} L[i][j]*x[j]
    Func xi_div("xi_div"); // final x[i] = xi / L[i][i]

    // RDom over j = 0 .. i_param-1  (dynamic extent depends on i_param)
    RDom r(0, i_param, "r");

    // Start from b[i]
    xi() = b_param(i_param);
    // Subtract contributions L[i][j] * x[j]
    // Recall: L[i][j] is stored as L_param(j, i_param)
    xi() -= L_param(r, i_param) * x_param(r);

    // Divide by the diagonal entry L[i][i] (L_param(i, i))
    xi_div() = xi() / L_param(i_param, i_param);

    // --------------------------
    // Scheduling for solve step
    // --------------------------

    // The computation for a single xi() is a scalar reduction over r.
    // We cannot parallelize in i (loop-carried dependency), but we can
    // make the inner reduction more efficient by unrolling.
    //
    // This keeps the iteration order over j the same logically, but
    // emits several multiply‑accumulate operations per loop iteration,
    // improving ILP and reducing loop overhead.
    xi.update().unroll(r, REDUCTION_UNROLL);

    // Bind ImageParams to our Buffers
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // JIT-compile the pipeline once
    xi_div.compile_jit();

    // Preallocate a 0‑dimensional Buffer to avoid tiny heap
    // allocations inside the timed loop. A 0‑dim buffer represents
    // a scalar in Halide.
    Halide::Buffer<num_t> xi_buf;

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
