    init_L
        .compute_root()
        .tile(j, i, jo, io, ji, ii, TILE_J, TILE_I)
        .parallel(io)
        .vectorize(ji, vec_width);

    // Actually realize into the provided buffers.
    init_x.realize(x);
    init_b.realize(b);
    init_L.realize(L);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one.
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation:
    //
    // For a fixed i:
    //   x[i] = b[i];
    //   for (j = 0; j < i; j++)
    //       x[i] -= L[i][j] * x[j];
    //   x[i] = x[i] / L[i][i];
    //
    // We keep the outer i-loop on the host to respect the dependence
    // x[i] <- {x[0..i-1]}.
    // For each fixed i, we express the inner sum over j as a Halide
    // reduction:
    //
    //   s(i) = sum_{j < i} L[i][j] * x[j]
    //   x[i] = (b[i] - s(i)) / L[i][i]
    //
    // This keeps algorithmic semantics identical while allowing Halide
    // to optimize the reduction over j.
    // -----------------------------------------------------------------

    Func sum("sum");        // sum_{j<i} L[i][j] * x[j]
    Func x_i_val("x_i_val"); // final scalar x[i] value

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // Dot product-like reduction: sum() = sum_j L[i][j] * x[j]
    sum() = cast<num_t>(0);
    // L[i][j] is stored as L_param(j, i_param)
    sum() += L_param(r, i_param) * x_param(r);

    // Final x[i] value: (b[i] - sum) / L[i][i]
    x_i_val() = (b_param(i_param) - sum()) / L_param(i_param, i_param);

    // Bind ImageParams to our Buffers (by reference; updates to x are visible).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // JIT-compile the scalar pipeline once for the host target.
    x_i_val.compile_jit(get_host_target());

    // Reuse a single 0-D buffer for the scalar result to avoid
    // per-iteration heap allocations.
    Halide::Buffer<num_t> xi_buf;

    // -----------------------------------------------------------------
    // Run the triangular solve, timing only the kernel-like part:
    // -----------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        // Set current row index
        i_param.set(i);

        // Realize scalar x_i_val() for this i into the reusable buffer.
        x_i_val.realize(xi_buf);

        // Update x[i] on the host; x_param refers to the same memory,
        // so subsequent iterations see the updated prefix x[0..i].
        x(i) = xi_buf();
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // -----------------------------------------------------------------
    // Print results (similar style to example/gemm.cpp)
    // -----------------------------------------------------------------
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            std::cerr << x(i) << '\n';
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
