using num_t = DATA_TYPE;

using namespace Halide;

/* Array initialization translated to Halide, with an explicit
 * schedule to improve data-locality and enable parallelism
 * and vectorization.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 2> L,  // logical L[i][j] stored as L(j, i)
                       Halide::Buffer<num_t, 1> x,
                       Halide::Buffer<num_t, 1> b) {
    Var i("i"), j("j");
    Func init_x("init_x"), init_b("init_b"), init_L("init_L");

    // x[i] = -999;
    init_x(i) = cast<num_t>(Expr(-999));

    // b[i] = i;
    init_b(i) = cast<num_t>(i);

    // L[i][j] = (DATA_TYPE) (i+n-j+1)*2/n for j <= i; 0 elsewhere (unused in kernel).
    // Remember: L is stored as L(j, i).
    Expr n_expr = cast<num_t>(Expr(n));
    Expr two    = cast<num_t>(Expr(2));

    init_L(j, i) = select(j <= i,
                          (cast<num_t>(i + n - j + 1) * two) / n_expr,
                          cast<num_t>(Expr(0)));

    // -------------------------
    // Scheduling for init phase
    // -------------------------

    // Use host target to pick a reasonable vector width for num_t.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    // 1D initializations: parallel over i, vectorize within each chunk.
    init_x
        .compute_root()
        .parallel(i)
        .vectorize(i, vec_width);

    init_b
        .compute_root()
        .parallel(i)
        .vectorize(i, vec_width);

    // 2D initialization of L: tile in (j, i), vectorize along j (fast varying),
    // and parallelize over tiles in the i (row) dimension.
    Var io("io"), jo("jo"), ii("ii"), ji("ji");

    // Tile sizes can be tuned for cache hierarchy; we keep them modest.
    const int tile_i = 32;              // rows per tile
    const int tile_j = 32 * vec_width;  // columns per tile (multiple of vector width)

    init_L
        .compute_root()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .parallel(io)          // parallel over row-tiles
        .vectorize(ji, vec_width);  // vectorize along inner j

    // Realize into the provided buffers.
    init_x.realize(x, target);
    init_b.realize(b, target);
    init_L.realize(L, target);
}

int main(int argc, char *argv[]) {
    // problem size
    int n = N;

    // Buffers:
    // L: original is L[i][j]; we store as L(j, i) so that the first
    // dimension (j) is the fast-varying one (row-major per logical row i).
    Halide::Buffer<num_t, 2> L(n, n);
    Halide::Buffer<num_t, 1> x(n);
    Halide::Buffer<num_t, 1> b(n);

    // ImageParams corresponding to L, x, b
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    ImageParam x_param(type_of<num_t>(), 1, "x_param");
    ImageParam b_param(type_of<num_t>(), 1, "b_param");

    // Scalar Param for the current row index i
    Param<int> i_param("i_param");

    // initialize data
    init_array(n, L, x, b);

    // Bind ImageParams to our Buffers once (the contents will be updated
    // in-place by the host for x).
    L_param.set(L);
    x_param.set(x);
    b_param.set(b);

    // -----------------------------------------------------------------
    // Halide formulation of the inner computation (for a fixed i):
    //
    //   // Forward substitution step
    //   sum = 0;
    //   for (j = 0; j < i; j++)
    //       sum += L[i][j] * x[j];
    //   x[i] = (b[i] - sum) / L[i][i];
    //
    // We express the j-loop as a Halide reduction (sum), and drive the
    // i-loop from the host, updating x one element at a time.
    // -----------------------------------------------------------------

    // RDom over j = 0 .. i_param-1
    RDom r(0, i_param, "r");

    // dot() computes sum_{j<i} L[i][j] * x[j] for the current i.
    Func dot("dot");
    dot() = cast<num_t>(Expr(0));
    // Recall: L[i][j] is stored as L_param(j, i_param)
    dot() += L_param(r, i_param) * x_param(r);

    // Final scalar value for x[i] = (b[i] - dot) / L[i][i]
    Func xi_div("xi_div");
    xi_div() = (b_param(i_param) - dot()) / L_param(i_param, i_param);

    // The default schedule for a scalar reduction (dot) in Halide is
    // already optimal for this pattern:
